// DLP scan + redact - deterministic layer 1. Mirrors gateway/dlp.py
// NOTE: JS has no Luhn here by default? We include it for cards.
function luhn(num){ const d=num.replace(/\D/g,''); if(d.length<13||d.length>19) return false; let s=0,alt=false; for(let i=d.length-1;i>=0;i--){let n=+d[i]; if(alt){n*=2; if(n>9)n-=9;} s+=n; alt=!alt;} return s%10===0; }
function mask(v){ return v.length<=8 ? '*'.repeat(v.length) : v.slice(0,4)+'********'+v.slice(-4); }
const body = $input.first().json.body || $input.first().json;
const raw = String(body.prompt || '').slice(0,20000);
let redacted = raw; const findings = [];
const rules = [
 ['aws_access_key','critical',/AKIA[0-9A-Z]{16}/g,'[REDACTED_AWS_KEY]',null],
 ['openai_api_key','critical',/sk-(?:proj-)?[A-Za-z0-9_\-]{20,}/g,'[REDACTED_OPENAI_KEY]',null],
 ['github_token','critical',/(?:ghp|gho|github_pat)_[A-Za-z0-9_]{20,}/g,'[REDACTED_GITHUB_TOKEN]',null],
 ['generic_password_assignment','critical',/(?:password|passwd|pwd|api[_-]?key|secret|token)\s*[:=]\s*\S{4,}/gi,'[REDACTED_CREDENTIAL]',null],
 ['credit_card','high',/(?:\d[ \-]?){13,19}/g,'[REDACTED_CREDIT_CARD]',luhn],
 ['us_ssn','high',/\b(?!000|666|9\d\d)\d{3}-(?!00)\d{2}-(?!0000)\d{4}\b/g,'[REDACTED_SSN]',null],
 ['email','medium',/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g,'[REDACTED_EMAIL]',null],
 ['phone_us','medium',/(?:\+1[ \-]?)?(?:\(?\d{3}\)?[ \-.]?)\d{3}[ \-.]?\d{4}/g,'[REDACTED_PHONE]',null],
];
for (const [type,sev,pat,ph,validator] of rules){
  const matches = [...redacted.matchAll(pat)];
  const valid = validator ? matches.filter(m=>validator(m[0])) : matches;
  if(!valid.length) continue;
  findings.push({type, severity:sev, count:valid.length, masked_preview:mask(valid[0][0])});
  redacted = redacted.replace(pat, (m)=> (!validator || validator(m)) ? ph : m);
}
const total = findings.reduce((a,f)=>a+f.count,0);
// Heuristic injection pre-filter (layer 2a) - mirrors gateway/injection_patterns.py (subset)
const heurRules = [
 ['ignore_previous',/ignore|disregard|forget/i, null],
];
let heuristic_score = 0; const heuristic_matched = [];
const heur = [
 ['ignore_previous',45,/\b(ignore|disregard|forget|override)\b.{0,40}\b(previous|prior|above)\b.{0,20}\b(instruction|prompt|rule)/i],
 ['dan_jailbreak',50,/\b(DAN|do anything now|jailbreak|developer mode)\b/i],
 ['system_prompt_extraction',50,/\b(repeat|print|show|reveal|output)\b.{0,50}\b(system prompt|your (initial )?instructions)/i],
 ['delimiter_injection',30,/(<\|im_start\|>|\[INST\]|###\s*(system|instruction))/i],
];
for (const [id,w,pat] of heur){ if(pat.test(redacted)){ heuristic_score+=w; heuristic_matched.push(id);} }
heuristic_score = Math.min(100, heuristic_score);
return [{ json: {
  prompt_raw_length: raw.length,
  redacted_prompt: redacted,
  dlp_findings: findings,
  dlp_critical: findings.some(f=>f.severity==='critical'),
  dlp_redactions: total,
  heuristic_score, heuristic_rules: heuristic_matched,
  session_id: body.session_id || null, source: body.source || 'n8n'
}}];

const prev = $('2. DLP + Heuristic Pre-Filter').first().json;
let cls = {injection_score: 0, category: 'none', rationale: 'classifier unavailable', action: 'allow'};
try { cls = JSON.parse($input.first().json.choices[0].message.content); } catch(e) {}
const finalScore = Math.max(prev.heuristic_score || 0, Number(cls.injection_score||0));
const shouldBlock =
  (prev.dlp_critical && true) || // STRICT_DLP_BLOCK=true in gateway config: secrets fail closed
  (cls.action === 'block' && finalScore >= 70) ||
  finalScore >= 85;
return [{ json: { ...prev, classifier: cls, injection_score: finalScore, blocked: shouldBlock,
  block_reason: prev.dlp_critical ? 'critical_dlp_secret_detected' : (shouldBlock ? 'prompt_injection_score_'+finalScore : null),
  category: cls.category !== 'none' ? cls.category : (prev.heuristic_score>=45 ? 'direct_injection' : 'none')
}}];

// Incident log payload - REDACTED prompt only, never raw.
// Route A (default): POST this JSON to your DB webhook / Supabase REST insert.
// Route B: see the disabled Postgres node '7b. Log Incident - Postgres (disabled)'.
const j = $input.first().json;
return [{ json: {
  source: 'n8n', session_id: j.session_id, category: j.category || 'none',
  injection_score: j.injection_score || 0, dlp_findings: j.dlp_findings,
  dlp_critical: j.dlp_critical, redacted_prompt: String(j.redacted_prompt||'').slice(0,2000),
  blocked: !!j.blocked, block_reason: j.block_reason, model: 'gpt-4o-mini'
}}];
